#ifndef __ASM_ARM_DMA_MAPPING_H
#define __ASM_ARM_DMA_MAPPING_H

#include <version_autogenerated.h>
#include "sys/types.h"
#include "stdio.h"

enum dma_data_direction {
	DMA_BIDIRECTIONAL	= 0,
	DMA_TO_DEVICE		= 1,
	DMA_FROM_DEVICE		= 2,
};

static void *dma_alloc_coherent(size_t len, unsigned int *handle)
{
	*handle = (unsigned int)malloc(len);

#ifdef CONFIG_ARCH_CKMMU
	*handle -= 0x80000000;
	return (void *)(*handle + 0x80000000);
#elif defined(CONFIG_ARCH_ARM)
	return (void *)*handle;
#else
#error "Not support current arch!!!"
#endif
}

static inline unsigned long dma_map_single(volatile void *vaddr, size_t len,
					   enum dma_data_direction dir)
{
#ifdef CONFIG_ARCH_CKMMU
	return (unsigned long)((unsigned long)vaddr - 0x80000000);
#elif defined(CONFIG_ARCH_ARM)
	return (unsigned long)vaddr;
#else
#error "Not support current arch!!!"
#endif
}

static inline void dma_unmap_single(volatile void *vaddr, size_t len,
				    unsigned long paddr)
{
}

#endif /* __ASM_ARM_DMA_MAPPING_H */
